//! Generates `tokens.rs` from `assets/design-tokens.json`, the design's token file, so colours and
//! metrics come straight from the design without parsing anything at startup.
//!
//! The generated file holds one `Palette` literal per theme (the struct is defined in `theme.rs`)
//! and a module of `f32` constants per metric group: `space::S4`, `radius::LG`,
//! `titlebar::CAPSULE_HEIGHT`, `text::BODY` and so on.

use std::fmt::Write;

use serde_json::Value;

const TOKENS: &str = "assets/design-tokens.json";

/// Colour roles shared by every theme, in `Palette` field order.
const ROLES: [&str; 24] = [
    "paper",
    "sidebar",
    "surface",
    "toolbar",
    "glass",
    "field",
    "raised",
    "fill",
    "fill_strong",
    "separator",
    "border",
    "scrim",
    "ink",
    "ink_2",
    "ink_3",
    "verse",
    "rubric",
    "accent",
    "on_accent",
    "accent_soft",
    "selection",
    "focus",
    "danger",
    "success",
];

/// Highlight colours in key order (1–6), matching `HighlightColor::ALL`.
const HIGHLIGHTS: [&str; 6] = ["yellow", "green", "blue", "pink", "purple", "orange"];

const SHADOWS: [&str; 5] = ["control", "panel", "popover", "modal", "knob"];

fn main() {
    println!("cargo:rerun-if-changed={TOKENS}");
    let src = std::fs::read_to_string(TOKENS).unwrap_or_else(|e| panic!("{TOKENS}: {e}"));
    let json: Value = serde_json::from_str(&src).unwrap_or_else(|e| panic!("{TOKENS}: {e}"));
    let mut out = String::from(
        "// @generated by build.rs from assets/design-tokens.json: edit the JSON, not this file.\n\n",
    );

    let color = &json["color"];
    // Highlights are `color.highlight.<name>.{swatch,<theme>}` (older files:
    // `color.highlight_swatch.<name>` and `color.<theme>.highlight.<name>`).
    let highlight = |h: &str, theme: Option<&str>| -> String {
        let new = &color["highlight"][h];
        let v = match theme {
            None if new.is_object() => &new["swatch"],
            None => &color["highlight_swatch"][h],
            Some(t) if new.is_object() => &new[t],
            Some(t) => &color[t]["highlight"][h],
        };
        hex(v, &format!("highlight.{h}.{}", theme.unwrap_or("swatch")))
    };
    let swatches: Vec<String> = HIGHLIGHTS.iter().map(|h| highlight(h, None)).collect();
    writeln!(out, "pub const SWATCHES: [Color32; 6] = [{}];\n", swatches.join(", ")).unwrap();
    for theme in ["light", "dark", "sepia"] {
        let c = &color[theme];
        writeln!(out, "pub static {}: Palette = Palette {{", theme.to_uppercase()).unwrap();
        for role in ROLES {
            writeln!(out, "    {role}: {},", hex(&c[role], &format!("{theme}.{role}"))).unwrap();
        }
        let hl: Vec<String> = HIGHLIGHTS.iter().map(|h| highlight(h, Some(theme))).collect();
        writeln!(out, "    highlights: [{}],", hl.join(", ")).unwrap();
        writeln!(out, "    swatches: SWATCHES,").unwrap();
        writeln!(out, "    shadows: Shadows {{").unwrap();
        for s in SHADOWS {
            // A CSS string, or `{ "css": …, "layers": … }`.
            let v = &json["shadow"][s][theme];
            let css =
                v.as_str().or_else(|| v["css"].as_str()).unwrap_or_else(|| panic!("shadow.{s}.{theme}"));
            writeln!(out, "        {s}: {},", elevation(css)).unwrap();
        }
        writeln!(out, "    }},\n}};\n").unwrap();
    }

    let traffic = &color["traffic_lights"];
    writeln!(out, "pub mod traffic_lights {{\n    use super::Color32;").unwrap();
    for k in ["close", "minimize", "zoom"] {
        writeln!(out, "    pub const {}: Color32 = {};", k.to_uppercase(), hex(&traffic[k], k)).unwrap();
    }
    writeln!(out, "}}\n").unwrap();

    // Type styles.
    writeln!(out, "pub mod text {{\n    use super::TypeStyle;").unwrap();
    let styles = json["type"]["styles"].as_object().expect("type.styles");
    for (name, s) in styles {
        let num = |k: &str| s[k].as_f64().unwrap_or_else(|| panic!("type.styles.{name}.{k}"));
        writeln!(
            out,
            "    pub const {}: TypeStyle = TypeStyle {{ reading: {}, size: {:?}, line_height: {:?}, weight: {}, tracking: {:?} }};",
            const_name(name),
            s["family"] == "reading",
            num("size") as f32,
            num("line_height") as f32,
            num("weight") as u16,
            num("tracking_em") as f32,
        )
        .unwrap();
    }
    writeln!(out, "}}\n").unwrap();

    // Numeric metric groups (`module`, JSON object).
    for (group, v) in [
        ("space", &json["space"]),
        ("radius", &json["radius"]),
        ("size", &json["size"]),
        ("titlebar", &json["titlebar"]),
        ("menu", &json["menu"]),
        ("icon", &json["icon"]),
        ("motion", &json["motion"]),
        ("reading", &json["type"]["reading"]),
        ("verse_number", &json["type"]["verse_number"]),
        ("state", &json["state"]),
    ] {
        let mut consts = Vec::new();
        flatten(v, "", group, &mut consts);
        writeln!(out, "pub mod {group} {{").unwrap();
        for (name, v) in consts {
            writeln!(out, "    pub const {name}: f32 = {v:?};").unwrap();
        }
        writeln!(out, "}}\n").unwrap();
    }

    let dest = std::path::Path::new(&std::env::var("OUT_DIR").unwrap()).join("tokens.rs");
    std::fs::write(dest, out).unwrap();

    web_files();
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("windows") {
        windows_resources();
    }
}

/// The bundled website files (`web/`, see `src/webview.rs`) as `web_files.rs`: a table of paths
/// and `include_bytes!`s. Only where the app has a webview; elsewhere the table is empty.
fn web_files() {
    const WEB: &str = "web";
    println!("cargo:rerun-if-changed={WEB}");
    let mut files = Vec::new();
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("macos") {
        collect(std::path::Path::new(WEB), &mut files);
    }
    files.sort();
    let root = std::fs::canonicalize(WEB).ok();
    let mut out =
        String::from("// @generated by build.rs from web/.\n\npub static FILES: &[(&str, &[u8])] = &[\n");
    for f in &files {
        let rel = f.strip_prefix(WEB).unwrap().to_string_lossy().replace('\\', "/");
        let abs = root.as_ref().unwrap().join(f.strip_prefix(WEB).unwrap());
        writeln!(out, "    ({rel:?}, include_bytes!({:?})),", abs.to_string_lossy()).unwrap();
    }
    out.push_str("];\n");
    let dest = std::path::Path::new(&std::env::var("OUT_DIR").unwrap()).join("web_files.rs");
    std::fs::write(dest, out).unwrap();
}

fn collect(dir: &std::path::Path, out: &mut Vec<std::path::PathBuf>) {
    let Ok(entries) = std::fs::read_dir(dir) else { return };
    for e in entries.flatten() {
        let path = e.path();
        if path.is_dir() {
            collect(&path, out);
        } else if path.file_name().is_some_and(|n| n != ".DS_Store" && n != "README.md") {
            out.push(path);
        }
    }
}

/// The Windows executable's icon, version information (publisher Fabrika LLC, the copyright
/// line of LICENSE, as the macOS bundle has) and manifest, from `packaging/windows`.
///
/// Building on Windows needs the Windows SDK's rc.exe (part of Visual Studio's C++ tools) or
/// MinGW's windres; cross-compiling needs llvm-rc (for -msvc) or x86_64-w64-mingw32-windres (for
/// -gnu). Without one a cross build goes on with a warning and an executable that has no icon.
fn windows_resources() {
    let manifest_dir = std::path::PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").unwrap());
    let root = manifest_dir.join("../..");
    let packaging = root.join("packaging/windows");
    let (icon, manifest, license) =
        (packaging.join("bible-rs.ico"), packaging.join("bible-rs.exe.manifest"), root.join("LICENSE"));
    for f in [&icon, &manifest, &license] {
        println!("cargo:rerun-if-changed={}", f.display());
    }
    let copyright = std::fs::read_to_string(&license)
        .ok()
        .and_then(|l| l.lines().find(|l| l.starts_with("Copyright")).map(str::to_string))
        .unwrap_or_default();
    let env = |k: &str| std::env::var(k).unwrap();
    let (version, major, minor, patch) = (
        env("CARGO_PKG_VERSION"),
        env("CARGO_PKG_VERSION_MAJOR"),
        env("CARGO_PKG_VERSION_MINOR"),
        env("CARGO_PKG_VERSION_PATCH"),
    );
    // Resource compilers take forward slashes in file names on every host.
    let path = |p: &std::path::Path| p.display().to_string().replace('\\', "/");
    let rc = format!(
        r#"1 ICON "{icon}"
1 24 "{manifest}"
1 VERSIONINFO
FILEVERSION {major},{minor},{patch},0
PRODUCTVERSION {major},{minor},{patch},0
FILEFLAGSMASK 0x3f
FILEFLAGS 0x0
FILEOS 0x40004
FILETYPE 0x1
FILESUBTYPE 0x0
BEGIN
  BLOCK "StringFileInfo"
  BEGIN
    BLOCK "040904b0"
    BEGIN
      VALUE "CompanyName", "Fabrika LLC"
      VALUE "FileDescription", "Bible"
      VALUE "FileVersion", "{version}"
      VALUE "InternalName", "bible-rs"
      VALUE "LegalCopyright", "{copyright}. MIT License."
      VALUE "OriginalFilename", "bible-rs.exe"
      VALUE "ProductName", "Bible"
      VALUE "ProductVersion", "{version}"
    END
  END
  BLOCK "VarFileInfo"
  BEGIN
    VALUE "Translation", 0x409, 1200
  END
END
"#,
        icon = path(&icon),
        manifest = path(&manifest),
        copyright = copyright.replace('"', "'"),
    );
    let rc_file = std::path::Path::new(&env("OUT_DIR")).join("bible-rs.rc");
    std::fs::write(&rc_file, rc).unwrap();
    match embed_resource::compile(&rc_file, embed_resource::NONE) {
        embed_resource::CompilationResult::Ok => {}
        other if cfg!(windows) => panic!("Windows resources: {other}"),
        other => println!("cargo:warning=Windows resources skipped ({other}); the .exe has no icon"),
    }
}

/// `#RRGGBB` or `#RRGGBBAA` as a `Color32` constructor.
fn hex(v: &Value, what: &str) -> String {
    let s = v.as_str().unwrap_or_else(|| panic!("{TOKENS}: missing colour {what}"));
    let h = s.strip_prefix('#').unwrap_or_else(|| panic!("{what}: {s} is not #hex"));
    let byte = |i: usize| u8::from_str_radix(&h[i..i + 2], 16).unwrap_or_else(|_| panic!("{what}: {s}"));
    let a = match h.len() {
        6 => 255,
        8 => byte(6),
        _ => panic!("{what}: {s} is not #RRGGBB(AA)"),
    };
    rgba(byte(0), byte(2), byte(4), a)
}

fn rgba(r: u8, g: u8, b: u8, a: u8) -> String {
    format!("Color32::from_rgba_unmultiplied_const({r}, {g}, {b}, {a})")
}

/// `rgba(r,g,b,a)` from CSS.
fn css_rgba(s: &str) -> String {
    let inner =
        s.trim().strip_prefix("rgba(").and_then(|s| s.strip_suffix(')')).unwrap_or_else(|| panic!("{s}"));
    let p: Vec<f64> = inner.split(',').map(|x| x.trim().parse().unwrap_or_else(|_| panic!("{s}"))).collect();
    rgba(p[0] as u8, p[1] as u8, p[2] as u8, (p[3] * 255.0).round() as u8)
}

/// The design's shadows are a hairline ring plus one drop shadow:
/// `0 0 0 <w>px rgba(…), 0 <y>px <blur>px rgba(…)`.
fn elevation(css: &str) -> String {
    let (ring, drop) = css.split_once("), ").unwrap_or_else(|| panic!("shadow {css}"));
    let ring = format!("{ring})");
    let len = |t: &str| t.trim_end_matches("px").parse::<f32>().unwrap_or_else(|_| panic!("shadow {css}"));
    let (ring_len, ring_color) = ring.split_once(" rgba").unwrap_or_else(|| panic!("shadow {css}"));
    let ring_width = len(ring_len.split_whitespace().nth(3).unwrap_or_else(|| panic!("shadow {css}")));
    let (drop_len, drop_color) = drop.split_once(" rgba").unwrap_or_else(|| panic!("shadow {css}"));
    let d: Vec<f32> = drop_len.split_whitespace().map(len).collect();
    format!(
        "Elevation {{ ring: {}, ring_width: {ring_width:?}, y: {:?}, blur: {:?}, color: {} }}",
        css_rgba(&format!("rgba{ring_color}")),
        d[1],
        d[2],
        css_rgba(&format!("rgba{drop_color}")),
    )
}

/// Collects numeric leaves of an object as `NAME_PATH` constants; strings and arrays are skipped.
fn flatten(v: &Value, prefix: &str, group: &str, out: &mut Vec<(String, f32)>) {
    let Some(obj) = v.as_object() else { panic!("{TOKENS}: {group} is not an object") };
    for (k, v) in obj {
        let name = if prefix.is_empty() { const_name(k) } else { format!("{prefix}_{}", const_name(k)) };
        // `space.4` becomes `space::S4`.
        let name = if name.starts_with(|c: char| c.is_ascii_digit()) {
            format!("{}{name}", group[..1].to_uppercase())
        } else {
            name
        };
        match v {
            Value::Number(n) => out.push((name, n.as_f64().unwrap() as f32)),
            Value::Object(_) => flatten(v, &name, group, out),
            _ => {}
        }
    }
}

fn const_name(k: &str) -> String {
    k.replace(['-', '.'], "_").to_uppercase()
}
